"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["79909"],{57226(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.documento_exigido.consequencia_incoerente_com_acao_da_vaga","status":422,"titulo":"A consequ\xeancia de indeferimento da exig\xeancia \xe9 incoerente com a a\xe7\xe3o de indeferimento da modalidade que ela alcan\xe7a"},"descricao":{"codigo":"uniplus.selecao.documento_exigido.consequencia_incoerente_com_acao_da_vaga","requisitos":["UNI-REQ-0070"],"oQueAconteceu":["Quando uma modalidade de vaga declara o que acontece com o candidato indeferido (a a\xe7\xe3o de\\nindeferimento), a consequ\xeancia de indeferimento do documento exigido tem de ser a mesma. O\\ndocumento apontado declara uma consequ\xeancia diferente da a\xe7\xe3o de uma modalidade que ele pode\\nalcan\xe7ar.","A compara\xe7\xe3o considera as modalidades ofertadas que a exig\xeancia pode alcan\xe7ar pelas condi\xe7\xf5es\\ndela, e s\xf3 as que declaram a\xe7\xe3o de indeferimento. A grafia diferente entre os dois\\nvocabul\xe1rios (`RECLASSIFICA_AC` na exig\xeancia e `RECLASSIFICAR_AC` na modalidade) \xe9 tratada como\\na mesma a\xe7\xe3o. A mensagem de detalhe indica o documento e a modalidade em conflito.","A confer\xeancia acontece quando a configura\xe7\xe3o vai ser congelada, na publica\xe7\xe3o ou na retifica\xe7\xe3o em ato \xfanico. Os documentos exigidos s\xe3o conferidos\\nprimeiro e, depois deles, os grupos de alternativas (OU) com consequ\xeancia pr\xf3pria (ver\\n[`no_exigencia.consequencia_incoerente_com_acao_da_vaga`](/erros/uniplus.selecao.no_exigencia.consequencia_incoerente_com_acao_da_vaga)).\\nA primeira viola\xe7\xe3o encontrada interrompe a confer\xeancia."],"comoResolver":["Alinhe a consequ\xeancia do documento \xe0 a\xe7\xe3o de indeferimento da modalidade apontada, ou revise\\na a\xe7\xe3o dessa modalidade, se for ela que est\xe1 errada. Depois, repita a opera\xe7\xe3o."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Documento exigido"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);